    /// The `character_reference` state, at `html/parsing#character-reference-state`.
    fn st_character_reference(&mut self) {
        self.clear_temp();
        self.push(Buf::Temp, '&');
        let input = self.consume();
        if input.is_some_and(|c| c.is_ascii_alphanumeric()) {
            self.reconsume_in(State::NamedCharacterReference);
        } else if input == Some('#') {
            self.push_current(Buf::Temp);
            self.switch(State::NumericCharacterReference);
        } else {
            // "Anything else"
            self.flush_temp();
            self.reconsume_return();
        }
    }

    /// The `ambiguous_ampersand` state, at `html/parsing#ambiguous-ampersand-state`.
    fn st_ambiguous_ampersand(&mut self) {
        let input = self.consume();
        if input.is_some_and(|c| c.is_ascii_alphanumeric()) {
            if self.test(Cond::InAttribute) {
                self.push_current(Buf::AttrValue);
            } else {
                self.emit_current();
            }
        } else if input == Some(';') {
            self.error("unknown-named-character-reference");
            self.reconsume_return();
        } else {
            // "Anything else"
            self.reconsume_return();
        }
    }

    /// The `numeric_character_reference` state, at `html/parsing#numeric-character-reference-state`.
    fn st_numeric_character_reference(&mut self) {
        self.char_ref_reset();
        let input = self.consume();
        if (input == Some('x')) || (input == Some('X')) {
            self.push_current(Buf::Temp);
            self.switch(State::HexadecimalCharacterReferenceStart);
        } else {
            // "Anything else"
            self.reconsume_in(State::DecimalCharacterReferenceStart);
        }
    }

